"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[4404],{65165:e=>{e.exports=JSON.parse('{"functions":[{"name":"spawnParticle","desc":"Emits one or more named particle effects at `source`.\\n\\n`source` may be a [BasePart] or [Model] to parent the emitters to (models use\\ntheir `PrimaryPart`), or a [Vector3]/[CFrame], in which case an invisible anchor\\npart is created in [Workspace] and cleaned up with the rest.\\n\\nBy default each emitter fires a single burst via `ParticleEmitter:Emit()`. Passing\\n`emissionTime` instead leaves the emitter enabled for that many seconds, and\\nextends the cleanup delay to match.\\n\\nEverything is tracked by the returned [Maid] and destroyed automatically once the\\neffect\'s lifetime is up; destroy the maid yourself to cut the effect short.\\n\\n```lua\\nspawnParticle({\\n\\tname = { \\"Impact.Sparks\\", \\"Impact.Smoke\\" },\\n\\tsource = hit.Position,\\n\\temission = 40,\\n})\\n```","params":[{"name":"data","desc":"","lua_type":"{ name: string | { string }, source: Vector3 | CFrame | BasePart | Model, size: Vector3 | number?, lifetime: number?, emission: number?, emissionTime: number? }"}],"returns":[{"desc":"Owns the emitters and any anchor part created for them","lua_type":"Maid.Maid"}],"function_type":"static","source":{"line":51,"path":"src/Shared/Modules/spawnParticle.luau"}}],"properties":[],"types":[],"name":"spawnParticle","desc":"Clones [ParticleEmitter]s out of `ReplicatedStorage.Assets.Particles`, plays them\\nat a position or on an instance, and cleans everything up afterwards.\\n\\nEmitters are looked up by dotted path within the Particles folder. A name that\\ndoes not resolve is warned about and skipped, so one missing asset does not stop\\nthe rest of a burst from playing.\\n\\nCopyright (c) 2026 firebit. All rights reserved.\\nfirebit/murder-escape - proprietary and confidential.","source":{"line":14,"path":"src/Shared/Modules/spawnParticle.luau"}}')}}]);